/**
 * KORA control catalogue (goal 09) — the single source of truth for `docs/governance/control-matrix.md`
 * and `.xlsx` (generated by `pnpm --filter @kora/api control-matrix`) and for the evidence export
 * (`GET /governance/controls/:id/evidence`). Every control names an automated evidence source that is
 * implemented in `evidence-queries.ts`; a unit test fails if one is missing.
 *
 * COBIT 2019 references name the governance/management objective and, where applicable, the
 * management practice. The 2nd line confirms them against the licensed COBIT 2019 publication
 * (OQ-G1); they are a mapping aid, not a certification claim.
 */

export const CONTROL_AREAS = [
  'access_mfa',
  'segregation_of_duties',
  'change_management',
  'audit_log_integrity',
  'pre_trade_risk',
  'reconciliation',
  'ai_oversight',
  'data_retention',
  'incident_management',
  'backup_restore',
  'compliance',
  'assurance',
] as const;
export type ControlArea = (typeof CONTROL_AREAS)[number];

export const AREA_LABELS: Record<ControlArea, string> = {
  access_mfa: 'Access and MFA',
  segregation_of_duties: 'Segregation of duties (four-eyes)',
  change_management: 'Change management',
  audit_log_integrity: 'Audit-log integrity',
  pre_trade_risk: 'Pre-trade risk limits',
  reconciliation: 'Reconciliation',
  ai_oversight: 'AI oversight',
  data_retention: 'Data retention and protection',
  incident_management: 'Incident management',
  backup_restore: 'Backup and restore',
  compliance: 'Compliance hooks',
  assurance: 'Independent assurance',
};

export type OwnerLine = 1 | 2 | 3;
export type Frequency = 'continuous' | 'per event' | 'every 60 s' | 'daily' | 'weekly' | 'monthly' | 'quarterly';

export interface ControlDefinition {
  id: string;
  area: ControlArea;
  title: string;
  objective: string;
  cobit: string[];
  risk: string;
  ownerLine: OwnerLine;
  owner: string;
  frequency: Frequency;
  nature: 'preventive' | 'detective' | 'corrective';
  automation: 'automated' | 'semi-automated';
  evidence: { kind: 'query' | 'report' | 'log'; source: string };
  testProcedure: string[];
  /** Audit actions that evidence this control (internal-audit sampling). */
  auditActions: string[];
}

